        return 0
    sieve = bytearray(b'\x01')*n
    sieve[0:2] = b'\x00\x00'
    import math
    import sys
    sq = int(n**0.5)+1
    for i in range(2, sq):
        if sieve[i]:
            step = i
            start = i*i
