def solve(n, edges):
    import heapq
    if n <= 0:
        return -1
    if n == 1:
        return 0
    adj=[[] for _ in range(n)]
    for e in edges:
        a,b,w=e
        if 0 <= a < n and 0 <= b < n:
            adj[a].append((b,w))
            adj[b].append((a,w))
    INF=float('inf')
    dist=[INF]*n
    dist[0]=0
    pq=[(0,0)]
    while pq:
        d,u=heapq.heappop(pq)
        if d!=dist[u]:
            continue
        if u==n-1:
            break
        for v,w in adj[u]:
            nd=d+w
            if nd<dist[v]:
