def solve(m):
    if not m or m == []:
        return 1
    n = len(m)
    # handle 0x0? empty matrix
    if n == 0:
        return 1
    A = [list(map(int, row)) for row in m]
    if n == 1:
        return A[0][0]
    sign = 1
    prev = 1
    for k in range(n-1):
        if A[k][k] == 0:
            swap = -1
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap == -1:
                return 0
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*A[k][k] - A[i][k]*A[k][j]) // prev
            A[i][k] = 0
        prev = A[k][k]
        if prev == 0:
            return 0
    return sign * A[n-1][n-1]

